import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync, readdirSync, statSync } from "node:fs";
import { join } from "node:path";
import { fileURLToPath } from "node:url";
import { assetFiles, writeAssets, pickerForBrowser, pickerRegistration, calendarSrcDir, OWN_ASSETS, relativeImports } from "../src/assets.js";
import { makeKit } from "./helpers.mjs";
import { tempDir } from "../../core/test/support/temp.mjs";

const ROOT = fileURLToPath(new URL("../", import.meta.url));

test("every asset the shell references ships in assets/", async () => {
  const { get } = makeKit("fa", { now: "2026-10-01T08:00:00Z" });
  const refs = new Set();
  for (const p of ["/blog/", "/podcasts/", "/glossary/"]) for (const m of (await (await get(p)).text()).matchAll(/(?:href|src)="\/kit\/([^"?]+)\?v=/g)) refs.add(m[1]);
  assert.deepEqual([...refs].sort(), ["format.js", "glossary.js", "kit.css", "kit.js", "podcast.js"]);
  refs.delete("format.js"); // generated from @saasreport/format by assetFiles (the kit's one number formatter)
  for (const f of refs) assert.ok(OWN_ASSETS.includes(f) && statSync(join(ROOT, "assets", f)).size > 100, f);
});

test("the assets base path is configurable", async () => {
  const { get } = makeKit("en", { options: { assets: { base: "/static/kit" } } });
  assert.match(await (await get("/blog/")).text(), /href="\/static\/kit\/kit\.css\?v=/);
});

test("browser copy of the date picker is in sync with @saasreport/calendar (generated by assetFiles)", async (t) => {
  const files = await assetFiles();
  const src = readFileSync(join(calendarSrcDir(), "picker-core.js"), "utf8"), reg = pickerRegistration(readFileSync(join(calendarSrcDir(), "picker.js"), "utf8"));
  const site = files.find((f) => f.path === "datepicker.js").content;
  const [banner, ...rest] = site.split("\n");
  assert.match(banner, /GENERATED from @saasreport\/calendar\/src\/picker-core\.js/);
  assert.ok(site.includes('from "./calendar.js";') && !site.includes('from "./index.js";'));
  assert.equal(rest.join("\n").replace('from "./calendar.js";', 'from "./index.js";'), src + reg);
  assert.match(reg, /definePicker\(DatePicker, /);
  assert.equal(site, pickerForBrowser(src, readFileSync(join(calendarSrcDir(), "picker.js"), "utf8")));
  const engine = files.find((f) => f.path === "calendar.js").content;
  assert.equal(engine.split("\n").slice(1).join("\n"), readFileSync(join(calendarSrcDir(), "index.js"), "utf8"));
  const dir = tempDir(t, "kit-assets-");
  const written = await writeAssets(dir);
  assert.equal(written.length, 11);
  // Every relative import of a browser module is shipped next to it (the picker's ./hijri.js was missing live).
  const paths = new Set(files.map((f) => f.path));
  for (const f of files.filter((x) => x.path.endsWith(".js"))) for (const dep of relativeImports(f.content)) assert.ok(paths.has(dep), `${f.path} imports ./${dep}, which is not an asset`);
  assert.deepEqual(relativeImports(site).sort(), ["calendar.js", "copy.js", "hijri.js"]);
  assert.equal(files.find((f) => f.path === "hijri.js").content.split("\n").slice(1).join("\n"), readFileSync(join(calendarSrcDir(), "hijri.js"), "utf8"));
  // the engine's Solar Hijri arithmetic (no imports) ships next to it, byte for byte
  assert.deepEqual(relativeImports(engine).sort(), ["copy.js", "instant.js"]);
  assert.equal(files.find((f) => f.path === "copy.js").content.split("\n").slice(1).join("\n"), readFileSync(join(calendarSrcDir(), "copy.js"), "utf8"));
  assert.equal(files.find((f) => f.path === "instant.js").content.split("\n").slice(1).join("\n"), readFileSync(join(calendarSrcDir(), "instant.js"), "utf8"));
  assert.equal(readFileSync(join(dir, "datepicker.js"), "utf8"), site);
});

test("client scripts parse", async () => {
  for (const f of OWN_ASSETS.filter((x) => x.endsWith(".js"))) assert.doesNotThrow(() => new Function(readFileSync(join(ROOT, "assets", f), "utf8")), f);
});

test("no project-specific (first consumer) names, texts, colours or URLs in src/ and assets/", () => {
  const BAD = /saasreport(?!-kit)|ایران اوپن|اوپن فاینانس|FF5A00|niloofar|kaveh|نیلوفر|کاوه|دو دقیقه مالی/i;
  const walk = (d) => readdirSync(d).flatMap((f) => (statSync(join(d, f)).isDirectory() ? walk(join(d, f)) : [join(d, f)]));
  const hits = [];
  for (const file of [...walk(join(ROOT, "src")), ...walk(join(ROOT, "assets")), ...walk(join(ROOT, "migrations"))]) {
    readFileSync(file, "utf8").split("\n").forEach((line, i) => {
      const clean = line.replace(/@saasreport\//g, "");
      if (BAD.test(clean)) hits.push(`${file.slice(ROOT.length)}:${i + 1}: ${line.trim().slice(0, 120)}`);
    });
  }
  assert.deepEqual(hits, []);
});
